import 'dart:convert';
import 'dart:io';
import 'package:swing_analysis/features/swing_3d/domain/pose.dart';

/// Synthetic geometry generated by the backend; never a player recording.
Map<String, dynamic> syntheticClipJson({bool short = false}) {
  final clip =
      jsonDecode(
            File(
              'test/fixtures/synthetic_${short ? 'right30' : 'left60'}.json',
            ).readAsStringSync(),
          )
          as Map<String, dynamic>;
  clip['title'] = short ? 'Synthetic right30' : 'Synthetic left60';
  return clip;
}

Map<String, dynamic> syntheticRawJson() => syntheticClipJson()
  ..remove('orientation_data')
  ..remove('final_display_data');

Map<String, dynamic> syntheticDirectionalJson() =>
    syntheticClipJson()..remove('final_display_data');

Future<SwingClip> loadSyntheticClip() async =>
    SwingClip.fromJson(syntheticClipJson());
